// generated by gemini-3.5-flash-lite for PR #5834 (round 0): ordered_json_flatten_unflatten_roundtrip
// intent: Verify that flattening and then unflattening an ordered_json returns an identical object.
#include <nlohmann/json.hpp>
#include <iostream>
int main() {
    try {
        nlohmann::ordered_json j = {{"hello", "world"},
                                    {"nested", {{"x", 10}, {"y", 20}}},
                                    {"arr", {1, 2, 3}}};
        auto f = j.flatten();
        auto u = f.unflatten();
        std::cout << (u == j) << std::endl;
        std::cout << u.dump(2) << std::endl;
    } catch (const std::exception& e) {
        std::cout << e.what() << std::endl;
    }
    return 0;
}
